    /**
     * Method to retrieve the DSP via DSPFetchOneSummary
     * @param 	summary DSPFetchOneSummary 
     * @return 	DSPFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public DSP getDSP( DSPFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DSPFetchOneSummary arg cannot be null" );
    	
    	DSP entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a DSP
        	// --------------------------------------
        	CompletableFuture<DSP> futureEntity = queryGateway.query(new FindDSPQuery( new LoadDSPFilter( summary.getDSPId() ) ), ResponseTypes.instanceOf(DSP.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate DSP with id " + summary.getDSPId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all DSPs
     *
     * @return 	List<DSP> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<DSP> getAllDSP() 
    throws ProcessingException {
        List<DSP> list = null;

        try {
        	CompletableFuture<List<DSP>> futureList = queryGateway.query(new FindAllDSPQuery(), ResponseTypes.multipleInstancesOf(DSP.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all DSP";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }


    /**
     * add AdAccount to AdAccounts 
     * @param		command AssignAdAccountsToDSPCommand
     * @exception	ProcessingException
     */     
	public void addToAdAccounts( AssignAdAccountsToDSPCommand command ) throws ProcessingException {
		
		
		// -------------------------------------------
		// load the parent
		// -------------------------------------------
		load( command.getDSPId() );

		AdAccountService childDelegate 	= AdAccountService.getAdAccountInstance();
		DSPService parentDelegate = DSPService.getDSPInstance();		
		UUID childId = command.getAddTo().getAdAccountId();
		
		try {		
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );			
		}
		catch( Exception exc ) {
			final String msg = "Failed to add a AdAccount as AdAccounts to DSP" ; 
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}

	}

